@font-face { font-family: "Silkscreen"; src: url("/assets/pixel-font.ttf") format("truetype"); font-display: swap; }
:root {
  --color-on-primary: #101c22;
  --color-gold: #f2cf7c;
  --color-background: #101518;
  --color-surface: #1c2429;
  --color-text: #edf1eb;
  --color-muted: #a6b8c2;
  --color-primary: #80d8ed;
  --color-primary-hover: #a3e7f5;
  --color-border: #41545e;
  --color-danger: #ffadad;
  --color-success: #a9d7b1;
  --color-scroll-thumb: #617b88;
  --radius-control: 0px;
  --radius-panel: 0px;
  --font-body: Tahoma, "Segoe UI", sans-serif;
  --font-display: "Silkscreen", "Consolas", monospace;
  --space-unit: 8px;
  --page-max: 1040px;
  --picker-surface: #182126;
  --picker-tile: #243138;
  --picker-border: #41545e;
  --picker-text: #edf1eb;
  --picker-muted: #a6b8c2;
  --picker-accent: #80d8ed;
  --z-dialog: 600;
  color-scheme: dark;
  scrollbar-color: var(--color-scroll-thumb) var(--color-background);
  scrollbar-width: auto;
  scrollbar-gutter: stable;
}
* { box-sizing: border-box; scrollbar-color: var(--color-scroll-thumb) var(--color-background); }
*::-webkit-scrollbar { width: 12px; height: 12px; }
*::-webkit-scrollbar-track { background: var(--color-background); }
*::-webkit-scrollbar-thumb { background: var(--color-scroll-thumb); border: 3px solid var(--color-background); border-radius: var(--radius-control); }
*::-webkit-scrollbar-thumb:hover { background: var(--color-muted); }
*::-webkit-scrollbar-thumb:active { background: var(--color-text); }
body { margin: 0; background: radial-gradient(#35454d66 1px, transparent 1px) 0 0 / 16px 16px, var(--color-background); color: var(--color-text); font: 16px/1.65 var(--font-body); }
.page { max-width: var(--page-max); margin: auto; padding: 28px 24px; }
.brand { display: flex; align-items: center; gap: 20px; margin-bottom: 26px; }
.brand-mark { width: 88px; height: 64px; image-rendering: pixelated; color: var(--color-primary); flex: 0 0 auto; }
h1 { font: 400 28px/1.35 var(--font-display); margin: 0; letter-spacing: -1px; }
.brand p { margin: 2px 0 0; color: var(--color-muted); }
.workspace { box-shadow: 6px 6px 0 #070b0d; background: var(--color-surface); border: 2px solid var(--color-border); border-radius: var(--radius-panel); padding: 26px 30px 20px; }
.steps { display: flex; align-items: center; justify-content: center; list-style: none; padding: 0; margin: 0 0 26px; gap: 36px; color: var(--color-muted); }
.steps li { display: flex; align-items: center; gap: 10px; font-weight: 600; }
.steps li + li::before { content: "→"; margin-right: 18px; color: var(--color-muted); }
.step-number { border-radius: 0; width: 34px; height: 34px; display: inline-grid; place-items: center; background: var(--color-background); border: 1px solid var(--color-border); }
.steps [aria-current] { color: var(--color-primary); }
.steps [aria-current] .step-number { color: var(--color-on-primary); background: var(--color-primary); border-color: var(--color-primary); }
.field-label, h2 { font-size: 20px; font-weight: 650; }
.field-label { display: block; margin-bottom: 8px; }
.link-controls { display: flex; gap: 10px; }
input[type="url"] { width: 100%; min-width: 0; padding: 12px 15px; border: 1px solid var(--color-border); border-radius: var(--radius-control); font: inherit; color: var(--color-text); background: var(--color-surface); }
input::placeholder { color: var(--color-muted); opacity: 1; }
input[aria-invalid="true"] { border-color: var(--color-danger); }
button, select, a { -webkit-tap-highlight-color: transparent; }
button, select { font: inherit; border-radius: var(--radius-control); }
button { cursor: pointer; min-height: 48px; border: 1px solid transparent; padding: 10px 20px; font-weight: 600; }
.primary { background: var(--color-primary); color: var(--color-on-primary); }
.primary:hover:enabled { background: var(--color-primary-hover); }
.primary:active:enabled { transform: translateY(1px); }
.check-button { width: 158px; flex: 0 0 158px; }
button:disabled { opacity: .52; cursor: not-allowed; }
button[aria-busy="true"] { cursor: wait; }
button[aria-busy="true"]::after { content: " …"; }
:focus-visible { outline: 3px solid var(--color-primary); outline-offset: 3px; }
.help { color: var(--color-muted); font-size: 14px; margin: 6px 0 0; }
.message-slot { min-height: 34px; }
.error { color: var(--color-danger); margin: 5px 0; font-size: 14px; overflow-wrap: anywhere; }
#media-section { border-top: 1px solid var(--color-border); padding-top: 22px; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
h2 { margin: 0; }
.empty-state { min-height: 252px; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; padding: 20px; }
.empty-state svg { color: var(--color-muted); width: 64px; height: 64px; margin-bottom: 8px; }
.empty-state p { margin: 6px 0 0; }
.preview { display: grid; grid-template-columns: minmax(200px, 38%) 1fr; gap: 28px; align-items: center; margin-bottom: 16px; }
.thumbnail-frame { aspect-ratio: 16 / 9; border-radius: var(--radius-control); overflow: hidden; background: var(--color-background); display: grid; place-items: center; color: var(--color-muted); font-size: 14px; }
.thumbnail-frame img { width: 100%; height: 100%; object-fit: contain; grid-area: 1 / 1; }
.thumbnail-frame span { grid-area: 1 / 1; }
h3 { margin: 0 0 12px; font-size: 20px; line-height: 1.5; overflow-wrap: anywhere; }
label { cursor: pointer; }
input[type="checkbox"] { accent-color: var(--color-primary); width: 21px; height: 21px; margin: 0 12px 0 0; vertical-align: middle; cursor: pointer; flex-shrink: 0; }
select { padding: 8px 10px; min-height: 44px; max-width: 200px; color: var(--color-text); background: var(--color-surface); border: 1px solid var(--color-border); cursor: pointer; }
.download-button { width: 100%; margin-top: 20px; min-height: 50px; }
.progress-panel { display: grid; grid-template-columns: minmax(200px, 1fr) 2fr; align-items: center; gap: 14px 24px; min-height: 58px; padding: 12px 14px; margin-top: 16px; border: 1px solid var(--color-border); border-radius: var(--radius-control); background: var(--color-background); }
.progress-panel p { margin: 0; font-size: 14px; }
progress { width: 100%; height: 12px; accent-color: var(--color-primary); border: 0; border-radius: var(--radius-control); overflow: hidden; }
progress::-webkit-progress-bar { background: var(--color-border); }
progress::-webkit-progress-value { background: var(--color-primary); border-radius: var(--radius-control); }
progress::-moz-progress-bar { background: var(--color-primary); }
.file-link { color: var(--color-primary); font-weight: 600; text-underline-offset: 3px; }
.file-link:hover { color: var(--color-primary-hover); }
.secondary { background: var(--color-surface); color: var(--color-text); border-color: var(--color-border); }
.secondary:hover { background: var(--color-background); }
.limits { color: var(--color-muted); font-size: 12px; margin: 14px 0 0; text-align: center; }
footer { color: var(--color-muted); font-size: 13px; text-align: center; margin-top: 14px; }
footer span { font-size: 12px; }
[hidden] { display: none !important; }
@media (max-width: 640px) {
  .page { padding: 20px 14px; }
  .brand { gap: 12px; margin-bottom: 20px; }
  h1 { font-size: 25px; }
  .brand p { font-size: 13px; }
  .brand-mark { width: 64px; height: 48px; }
  .workspace { padding: 20px 16px; }
  .steps { gap: 12px; font-size: 12px; margin-bottom: 24px; }
  .steps li { gap: 5px; }
  .steps li + li::before { display: none; }
  .step-number { width: 25px; height: 25px; }
  .link-controls { flex-direction: column; }
  .check-button { width: 100%; flex-basis: auto; }
  .preview { grid-template-columns: 1fr; gap: 16px; }
  h3 { font-size: 18px; }
  .progress-panel { grid-template-columns: 1fr; gap: 10px; }
  .field-label, h2 { font-size: 18px; }
  .section-heading { align-items: start; flex-direction: column; gap: 0; }
}
.picker-open { overflow: hidden; }
.media-picker > .picker-header, .media-picker > .picker-toolbar, .media-picker > .picker-footer { flex-shrink: 0; }
.media-picker { color-scheme: dark; color: var(--picker-text); background: var(--picker-surface); border: 2px solid var(--picker-border); border-radius: 0; padding: 22px; width: min(760px, calc(100% - 32px)); max-height: calc(100dvh - 40px); z-index: var(--z-dialog); box-shadow: 6px 6px 0 #060a0d; overflow: hidden; }
.media-picker[open] { display: flex; flex-direction: column; }
.media-picker::backdrop { background: #000b; backdrop-filter: blur(2px); }
.media-picker :focus-visible { outline-color: var(--picker-accent); }
.picker-header { display: flex; align-items: start; justify-content: space-between; gap: 16px; }
.picker-header h2 { font-size: 22px; line-height: 1.5; }
.picker-header p { margin: 4px 0 0; color: var(--picker-muted); font-size: 14px; }
.picker-close { font-size: 28px; line-height: 1; min-width: 44px; min-height: 44px; padding: 0; color: var(--picker-text); background: transparent; border-color: var(--picker-border); }
.picker-close:hover { background: var(--picker-tile); }
.picker-toolbar { display: flex; justify-content: space-between; align-items: center; padding: 16px 0; gap: 12px; font-size: 14px; color: var(--picker-muted); }
.media-picker input[type="checkbox"] { accent-color: var(--picker-accent); margin-right: 8px; }
.picker-body { min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-color: var(--picker-border) var(--picker-surface); padding: 3px; }
.media-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
.media-tile { min-width: 0; position: relative; background: var(--picker-tile); border: 2px solid var(--picker-border); border-radius: 0; overflow: hidden; }
.media-tile.is-selected { border-color: var(--picker-accent); }
.tile-preview { display: grid; place-items: center; position: relative; width: 100%; aspect-ratio: 1; border: 0; padding: 0; background: var(--picker-tile); color: var(--picker-text); border-radius: 0; overflow: hidden; }
.tile-preview:hover img { filter: brightness(1.1); }
.tile-preview img { width: 100%; height: 100%; object-fit: cover; grid-area: 1 / 1; opacity: 0; }
.tile-preview img.is-loaded { opacity: 1; }
.tile-placeholder { grid-area: 1 / 1; color: var(--picker-muted); font-size: 12px; padding: 12px; }
.tile-play { grid-area: 1 / 1; z-index: 1; border-radius: 0; background: #000b; color: var(--picker-text); width: 48px; height: 48px; display: grid; place-items: center; padding-left: 3px; font-size: 22px; }
.tile-selection { padding: 10px 8px; display: flex; align-items: center; color: var(--picker-text); font-size: 13px; min-height: 44px; }
.picker-footer { margin: 16px 0 0; }
.picker-footer button { width: 100%; color: var(--picker-surface); background: var(--picker-accent); min-height: 48px; border-radius: 0; }
.picker-footer button:hover { background: var(--picker-accent); }
.media-viewer { background: #101518; border: 1px solid var(--picker-border); border-radius: 0; padding: 12px; margin-bottom: 16px; }
.viewer-heading { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 10px; }
.viewer-heading h3 { margin: 0; font-size: 16px; }
.viewer-back { background: var(--picker-tile); color: var(--picker-text); font-size: 12px; padding: 8px 10px; }
#viewer-image, #viewer-video { display: block; max-width: 100%; width: 100%; max-height: 48dvh; object-fit: contain; background: #000; border-radius: 0; }
#viewer-status, #viewer-error { margin: 8px 0 0; font-size: 13px; min-height: 20px; color: var(--picker-muted); }
#viewer-error { color: #ffb6b6; }
@media (max-width: 640px) {
  .media-picker { padding: 16px; width: calc(100% - 20px); max-height: calc(100dvh - 24px); border-radius: 0; }
  .picker-header h2 { font-size: 19px; }
  .picker-header p { font-size: 12px; }
  .picker-toolbar { font-size: 12px; }
  .media-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
  .viewer-heading { align-items: start; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } }
.profile-controls { padding: 8px 0 16px; color: var(--picker-muted); font-size: 13px; }
.profile-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.profile-actions button { background: var(--picker-tile); color: var(--picker-text); border: 1px solid var(--picker-border); min-height: 44px; }
.profile-actions button:hover { border-color: var(--picker-accent); }
#profile-error { color: #ffb6b6; }
.post-caption { margin: 0; padding: 0 8px; font-size: 12px; color: var(--picker-text); overflow-wrap: anywhere; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.post-detail { padding: 0 8px; font-size: 12px; color: var(--picker-muted); }
#return-profile-picker { margin-bottom: 12px; }
@media (forced-colors: active) { * { scrollbar-color: auto; } button, input, select, .workspace { border: 1px solid ButtonText; } }

/* Shared pixel geometry; photos and videos retain their original rendering. */
.brand-copy { flex: 1; min-width: 0; }
.brand { gap: 18px; }
.language-switch { background: var(--color-surface); color: var(--color-text); border: 2px solid var(--color-border); white-space: nowrap; min-width: 76px; box-shadow: 3px 3px 0 #070b0d; }
.language-switch:hover { border-color: var(--color-gold); color: var(--color-gold); }
.window-rail { display: flex; align-items: center; gap: 7px; height: 20px; border-bottom: 2px solid var(--color-border); margin: -10px -14px 24px; padding: 0 8px 12px; }
.window-rail span { width: 5px; height: 5px; background: var(--color-muted); }
.window-rail span:first-child { background: var(--color-gold); }
.window-rail::after { content: ""; height: 2px; flex: 1; margin-left: 6px; background: var(--color-border); }
button { border-width: 2px; box-shadow: 3px 3px 0 #070b0d; }
button:active:enabled { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #070b0d; }
button:disabled { opacity: .5; box-shadow: none; }
.primary { border-color: #a4e7f4 #508c9d #508c9d #a4e7f4; }
.steps { border-bottom: 2px solid var(--color-border); padding-bottom: 24px; }
.step-number { border-width: 2px; box-shadow: 3px 3px 0 #070b0d; font-family: var(--font-display); }
.steps li + li::before { content: "›"; color: var(--color-border); }
input[type="url"] { border-width: 2px; background: var(--color-background); }
.empty-cat { width: 184px; height: 120px; image-rendering: pixelated; margin: 2px 0 12px; }
.empty-state { border: 2px dashed var(--color-border); background: #151d22; min-height: 260px; }
.empty-state p:first-of-type { font-weight: 700; }
.empty-state .help { max-width: 470px; }
#media-section { border-top-width: 2px; }
progress { height: 16px; border: 2px solid var(--color-border); padding: 2px; background: var(--color-background); }
progress::-webkit-progress-bar { background: var(--color-background); }
progress::-webkit-progress-value { background: repeating-linear-gradient(90deg, var(--color-primary) 0 10px, #599aa9 10px 12px); }
.progress-panel { border-width: 2px; }
.picker-header { padding-bottom: 14px; border-bottom: 2px solid var(--picker-border); }
.picker-header-actions { display: flex; align-items: center; gap: 10px; }
.picker-header-actions .language-switch { font-size: 12px; min-width: 64px; padding: 6px 8px; min-height: 44px; }
.tile-preview, .picker-close { box-shadow: none; }
.tile-selection { border-top: 2px solid var(--picker-border); }
.media-tile.is-selected { border-color: var(--picker-accent); background: #293e47; }
.media-viewer { border-width: 2px; }
#viewer-error, #profile-error { color: var(--color-danger); }
@media (max-width: 640px) {
  .page { padding: 20px 14px; }
  h1 { font-size: 19px; line-height: 1.5; letter-spacing: -1px; }
  .brand { gap: 10px; flex-wrap: wrap; }
  .brand-copy { flex-basis: calc(100% - 80px); }
  .brand > .language-switch { margin-left: auto; min-height: 40px; padding: 6px 12px; font-size: 13px; }
  .brand p { font-size: 12px; }
  .window-rail { margin: -4px -6px 20px; }
  .steps { gap: 16px; justify-content: space-between; }
  .empty-cat { width: 160px; height: 104px; }
  .empty-state { padding: 16px 10px; }
  .picker-header { gap: 8px; }
  .picker-header-actions { gap: 8px; flex-wrap: wrap; justify-content: flex-end; }
  .picker-header-actions .language-switch { min-width: 56px; }
}

.quality-note { color: var(--picker-accent); font-size: 12px; margin: 0; padding: 0 8px 8px; }
.audio-choice { display: flex; align-items: center; padding: 6px 8px 10px; font-size: 12px; min-height: 44px; color: var(--picker-muted); }
.audio-choice input { width: 17px; height: 17px; }


.brand-controls { margin-left: auto; display: flex; align-items: center; gap: 10px; }
.motion-toggle { font-size: 12px; }
.cat-scene { --cat-chew-image: url("data:image/png;base64,"); position: relative; width: 184px; height: 120px; flex: 0 0 auto; margin: 2px 0 12px; }
.cat-scene .empty-cat { display: block; margin: 0; width: 100%; height: 100%; }
.cat-output { position: absolute; left: 58%; top: 46%; width: 24px; height: 24px; opacity: 0; pointer-events: none; shape-rendering: crispEdges; }
.cat-chew { position: absolute; left: 0; top: 0; width: 77.173913%; height: 100%; opacity: 0; image-rendering: pixelated; background-image: var(--cat-chew-image); background-repeat: no-repeat; background-size: 238.768116% 112.288136%; }
.cat-chew-closed { background-position: 4.177546% 47.126437%; }
.cat-chew-open { background-position: 90.165361% 47.126437%; }
html[data-cat-motion="on"] .cat-scene[data-state="chewing"][data-ready="true"] .empty-cat { opacity: 0; }
/* This explicit app preference controls only the cat, including when OS motion is reduced. */
html[data-cat-motion="on"] .cat-scene[data-state="chewing"][data-ready="true"] .cat-chew-closed { animation: cat-chew-closed 440ms steps(1, end) infinite !important; }
html[data-cat-motion="on"] .cat-scene[data-state="chewing"][data-ready="true"] .cat-chew-open { animation: cat-chew-open 440ms steps(1, end) infinite !important; }
html[data-cat-motion="on"] .cat-scene[data-state="spitting"] .cat-photo { animation: cat-spit-photo 620ms steps(6, end) both !important; }
html[data-cat-motion="on"] .cat-scene[data-state="spitting"] .cat-video { animation: cat-spit-video 620ms steps(6, end) both !important; }
html[data-cat-motion="on"] .cat-scene[data-state="spitting"] .empty-cat { animation: cat-pop 300ms steps(3, end) !important; }
@keyframes cat-chew-closed { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
@keyframes cat-chew-open { 0%, 49% { opacity: 0; } 50%, 100% { opacity: 1; } }
@keyframes cat-spit-photo { 0% { opacity: 0; transform: translate(0, 0) scale(.4); } 20% { opacity: 1; } 75% { opacity: 1; } 100% { opacity: 0; transform: translate(52px, -28px) rotate(12deg); } }
@keyframes cat-spit-video { 0%, 10% { opacity: 0; transform: translate(0, 0) scale(.4); } 30% { opacity: 1; } 75% { opacity: 1; } 100% { opacity: 0; transform: translate(42px, 22px) rotate(-8deg); } }
@keyframes cat-pop { 0%, 100% { transform: translate(0, 0); } 40% { transform: translate(-3px, 0); } 70% { transform: translate(1px, -2px); } }
@media (max-width: 640px) { .cat-scene { width: 160px; height: 104px; } .brand-controls { flex-wrap: wrap; justify-content: flex-end; } }

