html[data-paw-cursor="on"], html[data-paw-cursor="on"] * { cursor: none !important; }
#paw-cursor { position: fixed; inset: auto; left: 0; top: 0; margin: 0; padding: 0; width: 32px; height: 32px; border: 0; background: transparent; overflow: visible; pointer-events: none; user-select: none; opacity: 0; transform: translate3d(calc(var(--paw-x, -100px) - 16px), calc(var(--paw-y, -100px) - 4px), 0); }
#paw-cursor::backdrop { background: transparent; pointer-events: none; }
#paw-cursor[data-visible="true"] { opacity: 1; }
.paw-press, .paw-rotor { display: block; width: 32px; height: 32px; transform-origin: 16px 16px; }
#paw-cursor svg { display: block; width: 32px; height: 32px; overflow: visible; }
#paw-cursor .paw-pads { fill: var(--color-primary); }
#paw-cursor[data-kind="pointer"] .paw-pads, #paw-cursor[data-kind="text"] .paw-pads { fill: var(--color-gold); }
#paw-cursor[data-kind="disabled"] .paw-pads { fill: var(--color-danger); }
#paw-cursor[data-pressed="true"] .paw-press { transform: scale(.84); }
.paw-caret, .paw-stop, .paw-dots { display: none; }
#paw-cursor[data-kind="text"] .paw-caret, #paw-cursor[data-kind="disabled"] .paw-stop, #paw-cursor[data-kind="busy"] .paw-dots { display: block; }
html[data-cat-motion="on"] #paw-cursor[data-kind="busy"] .paw-rotor { animation: paw-spin 900ms steps(8, end) infinite !important; }
@keyframes paw-spin { to { transform: rotate(360deg); } }
@media (forced-colors: active) { html, body, body * { cursor: auto !important; } #paw-cursor { display: none; } }

.output-options { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; margin-top: 24px; }
.output-options label { font-weight: 700; }
.output-options .help { flex-basis: 100%; margin: 0; }
